isher_type":null,"city":"Sopron","country_code":"HU","endpoint_url":"https://www.visitsopron.com/hu/programok-1","original_endpoint_url":"https://www.visitsopron.com/hu/programok-1","format":"HTML eseménylista","categories":["Városi programok","Kulturális program","Kiállítás","Fesztivál","Koncert"],"legal_basis":"Hivatalos publikus oldal; önkormányzati tulajdonú városmarketing cég üzemelteti","audit_status":null,"dedupe_priority":2,"parser_strategy":"HTML eseménylink-extractor a listaoldalról (dátum/település/helyszín szűrők és a \"Továbbiak\" lapozás követésével), detail-oldalanként structured-data (JSON-LD/meta) és dátum-parszolás; QARD platform miatt érdemes XHR/JSON endpoint felderítést is futtatni","notes":"Felfedezve a 2026-09-04-i külső crawlban; endpoint élő lekéréssel ellenőrizve és adverzariálisan visszaigazolva.","fetch_hosts":["www.visitsopron.com"]}]$feed_v5$::jsonb;
BEGIN
  IF jsonb_array_length(v_candidates) <> 9 THEN
    RAISE EXCEPTION 'EVENT_FEED_V5_SEED_COUNT_INVALID';
  END IF;

  INSERT INTO public.external_event_feed_sources (
    source_id,
    publisher_name,
    publisher_type,
    city,
    country_code,
    endpoint_url,
    original_endpoint_url,
    format,
    categories,
    legal_basis,
    audit_status,
    dedupe_priority,
    parser_strategy,
    notes,
    fetch_hosts,
    review_state,
    legal_review_status,
    robots_allowed,
    enabled
  )
  SELECT
    candidate ->> 'source_id',
    candidate ->> 'publisher_name',
    NULLIF(candidate ->> 'publisher_type', ''),
    NULLIF(candidate ->> 'city', ''),
    NULLIF(candidate ->> 'country_code', ''),
    NULLIF(candidate ->> 'endpoint_url', ''),
    candidate ->> 'original_endpoint_url',
    NULLIF(candidate ->> 'format', ''),
    ARRAY(SELECT jsonb_array_elements_text(candidate -> 'categories')),
    NULLIF(candidate ->> 'legal_basis', ''),
    NULLIF(candidate ->> 'audit_status', ''),
    NULLIF(candidate ->> 'dedupe_priority', '')::integer,
    NULLIF(candidate ->> 'parser_strategy', ''),
    NULLIF(candidate ->> 'notes', ''),
    ARRAY(SELECT jsonb_array_elements_text(candidate -> 'fetch_hosts')),
    'pending_review',
    'pending',
    NULL,
    false
  FROM jsonb_array_elements(v_candidates) AS source(candidate)
  -- Host-level guard: ON CONFLICT only protects the source_id, so a candidate whose
  -- HOST is already registered under a different id would still slip in as a duplicate
  -- source. Skip those, in whatever state the target database happens to be.
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.external_event_feed_sources existing
    WHERE existing.endpoint_url IS NOT NULL
      AND lower(regexp_replace(split_part(regexp_replace(existing.endpoint_url, '^https?://', ''), '/', 1), '^www\.', ''))
        = lower(regexp_replace(split_part(regexp_replace(candidate ->> 'endpoint_url', '^https?://', ''), '/', 1), '^www\.', ''))
  )
  ON CONFLICT (source_id) DO NOTHING;
END;
